// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function testFuzz_property(uint256 amount, uint256 actorSeed) public {
        // Keep amounts within a sane, still-wide domain.
        amount = bound(amount, 1 ether, 100 ether);

        // Deploy an adversarial callee that always reverts on receiving ETH,
        // so the external transfer from Collect always fails.
        Reverter reverter = new Reverter();

        // Wire c's LogFile to a harmless deployed LogFile-like handle so that
        // Deposit's AddMessage call does not revert (required setup).
        LogFileRecorder logRec = new LogFileRecorder();
        c.SetLogFile(address(logRec));

        // The caller must be an address whose ETH transfer will fail. We use
        // the Reverter contract itself as the caller by having it call Collect.
        // Fund the Reverter so it can attempt a deposit / have a balance.
        vm.deal(address(reverter), amount);

        // The caller/reverter deposits into c so its balance within c is >= amount.
        uint256 minSum = c.MinSum();
        amount = bound(amount, minSum, 100 ether);
        vm.deal(address(reverter), amount);

        // Let the Reverter contract call Deposit on c with `amount`.
        reverter.depositTo(address(c), amount);

        // Sanity: the caller's internal balance in c must be at least amount.
        // (If not, skip — but with the deposit above it will be.)
        uint256 balBefore = c.balances(address(reverter));
        vm.assume(balBefore >= amount);

        // Now let the Reverter call Collect. Because Reverter's receive/fallback
        // reverts, the ETH transfer back to it fails.
        // On the reference, Collect reverts and the balance is unchanged.
        // On the mutant, Collect succeeds and the balance is reduced by amount.
        try reverter.collectFrom(address(c), amount) {
            // MUTANT PATH: Collect succeeded despite failed ETH transfer.
        } catch {
            // REFERENCE PATH: Collect reverted atomically.
        }

        uint256 balAfter = c.balances(address(reverter));

        // GENERAL RULE: if Collect completes successfully for a caller whose
        // external ETH transfer reverts, then the caller's balance must not
        // have been reduced. Equivalently, since the transfer always reverts
        // here, the reference keeps balAfter == balBefore; the mutant reduces it.
        assertTrue(balAfter == balBefore);
    }
}

// Adversarial callee: its receive()/fallback() alway reverts, so any ETH
// transfer to it from c.Collect will fail.
contract Reverter {
    function depositTo(address target, uint256 amount) external payable {
        (bool ok, ) = target.call{value: amount}(
            abi.encodeWithSignature("Deposit()")
        );
        require(ok, "deposit failed");
    }

    function collectFrom(address target, uint256 amount) external {
        (bool ok, ) = target.call(
            abi.encodeWithSignature("Collect(uint256)", amount)
        );
        require(ok, "collect failed");
    }

    receive() external payable {
        revert("no ETH accepted");
    }

    fallback() external payable {
        revert("no fallback");
    }
}

// Minimal LogFile-compatible recorder so c.Deposit's Log.AddMessage call does
// not revert. It records messages but the test does not assert on them.
contract LogFileRecorder {
    struct Message {
        address Sender;
        string Data;
        uint256 Val;
        uint256 Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
